(() => {
  'use strict';
  const $=id=>document.getElementById(id), E=VetEngine;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=(n,d=0)=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
  const brand=x=>x==='rc'?'로얄캐닌':'힐스', species=x=>x==='dog'?'강아지':'고양이';
  const unit={kg:'kcal/kg','100g':'kcal/100g',g:'kcal/g',pack:'kcal/캔·파우치'};
  const date=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});
  const safeURL=url=>/^https?:\/\//i.test(url||'')?esc(url):'';
  const clone=x=>JSON.parse(JSON.stringify(x));
  const key='vetdiet.local.v1',demo=new URLSearchParams(location.search).get('demo')==='1'; let custom=[],records=[],selected=null,secondary=null,lastResult=null,manualChoice=false;
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
  function catalog(){const map=new Map(VetCatalog.map(p=>[p.id,p]));custom.forEach(p=>map.set(p.id,p));return[...map.values()];}
  function product(id){return catalog().find(p=>p.id===id)||null;}
  function persist(nextCustom=custom,nextRecords=records){try{if(!demo)localStorage.setItem(key,JSON.stringify({version:1,custom:nextCustom,records:nextRecords}));custom=nextCustom;records=nextRecords;return true;}catch{toast('저장할 수 없습니다. 브라우저 저장 공간을 확인하고 자료를 백업하세요.');return false;}}
  try{const raw=demo?null:localStorage.getItem(key);if(raw){const data=validateBackup(JSON.parse(raw));custom=data.custom;records=data.records;}}catch{toast('저장 자료를 읽을 수 없습니다. 원본은 유지했습니다. 백업 불러오기를 이용하세요.');}
  if(demo)document.querySelector('.local-badge').textContent='가상 환자 검증 · 영구 저장 안 됨';
  function patient(){const p={name:$('name').value.trim(),species:document.querySelector('[name=species]:checked').value,conditions:[...document.querySelectorAll('[name=condition]:checked')].map(x=>x.value),energyMode:$('energy-mode').value,mixed:$('mixed').checked,manualChoice};for(const id of ['weight','age','life','neuter','activity','bcs','mcs','goal','target','clinical','factor','manual','treats','meals','ratio','recheck','instructions'])p[id]=$(id).value;return p;}
  function setPatient(p){manualChoice=p.manualChoice===true;$('name').value=p.name;document.querySelector(`[name=species][value=${p.species}]`).checked=true;for(const id of ['weight','age','life','neuter','activity','bcs','mcs','goal','target','clinical','factor','manual','treats','meals','ratio','recheck','instructions'])$(id).value=p[id]??'';$('energy-mode').value=p.energyMode;$('mixed').checked=p.mixed;document.querySelectorAll('[name=condition]').forEach(x=>x.checked=p.conditions.includes(x.value));}
  function switchTab(name){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===name);b.setAttribute('aria-current',b.dataset.tab===name?'page':'false');});if(name==='catalog')renderLibrary();if(name==='records')renderRecords();}
  document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
  function energyLabel(p){return p.energy?`${fmt(p.energy, p.energyUnit==='g'?2:0)} ${unit[p.energyUnit]}`:'포장 열량 입력 필요';}
  function filteredCandidates(){const p=patient();return E.candidates(catalog(),p).filter(x=>($('brand-filter').value==='all'||x.brand===$('brand-filter').value)&&($('type-filter').value==='all'||x.type===$('type-filter').value)&&(`${x.name} ${x.purposes.map(k=>E.labels[k]).join(' ')}`.toLowerCase().includes($('search').value.trim().toLowerCase())));}
  function renderCandidates(){const list=filteredCandidates();$('candidate-count').textContent=`${list.length}개 후보`;$('candidates').innerHTML=list.length?list.map(x=>`<article class="diet-card ${selected===x.id?'selected':''}"><div class="diet-top"><span class="brand-label ${esc(x.brand)}">${brand(x.brand)}</span><span class="pill">${x.type==='dry'?'건식':'습식'}</span></div><h3>${esc(x.name)}</h3><p>${esc(x.purposes.map(k=>E.labels[k]).join(' · '))} 용도로 등록된 제품</p><div class="diet-bottom"><span>${esc(energyLabel(x))}</span><button data-select="${esc(x.id)}" aria-pressed="${selected===x.id}">${selected===x.id?'선택됨':'선택'}</button></div></article>`).join(''):'<div class="empty">등록된 용도와 환자 조건을 모두 충족하는 후보가 없습니다.<br>질환별 식이 목표를 검토하거나 사료 자료실에서 제품 정보를 보완하세요.</div>';}
  function detailHTML(x,second=false){if(!x)return'';return`<div class="detail"><h3>${second?'두 번째 제품':'선택한 제품'} · ${esc(x.name)}</h3><p>${esc(x.notes)}</p>${x.contra.length?`<details><summary>제조사 비권장 상황의 원문 코드</summary><p class="source-text">${x.contra.map(c=>`${esc(c.label)} (${esc(c.code)})`).join('<br>')}</p></details>`:''}<p>자료 확인일: ${esc(x.checkedAt)} · 열량 출처: ${esc(x.energySource)}</p><div class="actions">${safeURL(x.url)?`<a href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">공식 제품 자료</a>`:''}<button data-edit="${esc(x.id)}">열량·제품 정보 수정</button></div>${x.energy?`<label class="check" style="margin-top:16px"><input data-label-check="${esc(x.id)}" type="checkbox" ${x.labelConfirmed?'checked':''}>${esc(energyLabel(x))} 값이 실제 제품 포장과 일치합니다.</label>`:'<p class="warning">확인 가능한 포장 열량을 입력해야 급여량을 계산할 수 있습니다.</p>'}</div>`;}
  function renderDetails(){const x=product(selected),y=$('mixed').checked?product(secondary):null;$('selected-detail').innerHTML=x?detailHTML(x)+(y?detailHTML(y,true):''):'<div class="detail"><p>제품을 선택하면 열량 출처와 확인 항목이 표시됩니다.</p></div>';}
  function renderSecondary(){const list=E.candidates(catalog(),patient()).filter(x=>x.id!==selected);if(secondary&&!list.some(x=>x.id===secondary))secondary=null;$('secondary-product').innerHTML='<option value="">두 번째 제품 선택</option>'+list.map(x=>`<option value="${esc(x.id)}">${brand(x.brand)} · ${esc(x.name)} (${x.type==='dry'?'건식':'습식'})</option>`).join('');$('secondary-product').value=secondary||'';}
  function render(){const p=patient();$('target-wrap').hidden=p.goal!=='loss';$('factor-wrap').hidden=p.energyMode!=='factor';$('manual-wrap').hidden=p.energyMode!=='manual';$('mix-controls').hidden=!p.mixed;$('bcs-value').textContent=`${p.bcs} / 9`;
    const all=E.candidates(catalog(),p);if(selected&&(!product(selected)||product(selected).species!==p.species||(!manualChoice&&!all.some(x=>x.id===selected)))){selected=null;manualChoice=false;}renderCandidates();renderSecondary();renderDetails();
    if(manualChoice&&selected)$('selected-detail').insertAdjacentHTML('afterbegin','<p class="warning">수의사가 자료실에서 직접 선택한 제품입니다. 후보 필터의 용도 일치 여부와 별개로 적합성을 검토하세요.</p>');
    lastResult=E.calculate(p,product(selected),p.mixed?product(secondary):null);const r=lastResult;
    $('energy-summary').innerHTML=`<span>${p.energyMode==='manual'?'수의사 지정 목표 열량':'초기 목표 열량'}</span><strong>${fmt(r.total)} <small>kcal / 일</small></strong><p>${Number.isFinite(r.baseRer)?`기준 체중 ${fmt(r.baseWeight,1)} kg · RER ${fmt(r.baseRer)} kcal${r.factor!==null?' × '+fmt(r.factor,2):''}`:'현재 체중을 입력하세요.'}</p>`;
    $('feeding-result').innerHTML=r.ok?r.amounts.map(a=>`<div class="quantity"><h3>${esc(a.name)}</h3><strong>${fmt(a.grams,1)} <small>g / 일</small></strong><p>한 끼 ${fmt(a.perMeal,1)} g · 하루 ${esc(p.meals)}회</p>${a.packs!==null?`<p>${fmt(a.packs,2)} 캔·파우치 / 일 (${product(a.id).packGrams} g 포장)</p>`:''}<p>${fmt(a.kcal,1)} kcal / 일 · ${fmt(a.density,3)} kcal/g</p></div>`).join(''):'<p class="muted">필수 입력과 제품 열량 확인이 완료되면 급여량이 표시됩니다.</p>';
    $('alerts').innerHTML=r.errors.map(t=>`<p class="error">${esc(t)}</p>`).join('')+r.warnings.map(t=>`<p class="warning">${esc(t)}</p>`).join('');
    $('clinical-notes').innerHTML=p.conditions.length?'<p class="notice">질병 단계·검사 결과·동반 질환과 제품의 제한사항을 기록하세요.</p>':'';
    for(const id of ['save','copy','print'])$(id).disabled=!(r.ok&&$('reviewed').checked);
  }
  function invalidate(){$('reviewed').checked=false;render();}
  $('patient-form').addEventListener('input',invalidate);
  document.querySelector('.result-controls').addEventListener('input',event=>{if(event.target.id==='secondary-product')secondary=event.target.value||null;invalidate();});
  for(const id of ['brand-filter','type-filter','search'])$(id).addEventListener('input',renderCandidates);
  for(const id of ['recheck','instructions'])$(id).addEventListener('input',invalidate);
  $('reviewed').addEventListener('change',render);
  $('candidates').addEventListener('click',event=>{const b=event.target.closest('[data-select]');if(!b)return;selected=b.dataset.select;secondary=null;manualChoice=false;invalidate();});
  $('selected-detail').addEventListener('click',event=>{const b=event.target.closest('[data-edit]');if(b)openEditor(product(b.dataset.edit));});
  $('selected-detail').addEventListener('change',event=>{const id=event.target.dataset.labelCheck;if(!id)return;const p=clone(product(id));p.labelConfirmed=event.target.checked;if(persist([...custom.filter(x=>x.id!==id),p]))invalidate();});
  $('reset').addEventListener('click',()=>{if(($('name').value||$('weight').value)&&!confirm('현재 입력을 초기화하고 새 환자 계획을 작성할까요? 저장된 기록은 유지됩니다.'))return;$('patient-form').reset();for(const [id,v]of Object.entries({'energy-mode':'auto',factor:'1.6',manual:'',treats:'0',meals:'2',ratio:'70',recheck:'',instructions:''}))$(id).value=v;$('mixed').checked=false;selected=null;secondary=null;invalidate();});
  function makeRecord(){const p=patient(),r=E.calculate(p,product(selected),p.mixed?product(secondary):null);if(!r.ok||!$('reviewed').checked)throw Error('입력값과 제품 적합성을 검토한 후 진행하세요.');return{id:crypto.randomUUID(),savedAt:new Date().toISOString(),date:date(),patient:p,products:clone(p.mixed?[product(selected),product(secondary)]:[product(selected)]),result:r};}
  function report(record,owner=false){const p=record.patient,r=record.result;const lines=[owner?'환자 식이 급여 안내':'진료용 식이 계획',`환자: ${p.name||'미입력'} · ${species(p.species)} · 작성일 ${record.date}`,`현재 체중 ${fmt(Number(p.weight),1)} kg${p.goal==='loss'?' / 목표 체중 '+fmt(Number(p.target),1)+' kg':''}`,`영양 목표: ${{maintain:'체중 유지',loss:'체중 감량',gain:'체중 증량'}[p.goal]}`,`하루 목표 ${fmt(r.total,1)} kcal · 기타 음식 ${fmt(Number(p.treats),1)} kcal · 사료 공급 ${fmt(r.food,1)} kcal`];if(!owner){lines.push(`BCS ${p.bcs}/9 · MCS ${p.mcs} · 나이 ${p.age}개월`,p.energyMode==='manual'?'목표 열량 직접 지정':`RER = 70 × ${r.baseWeight}^0.75 = ${fmt(r.baseRer,1)} kcal / 계수 ${fmt(r.factor,2)}`,`식이 관리 조건: ${p.conditions.map(k=>E.labels[k]).join(', ')||'없음'}`,`임상 기록: ${p.clinical||'없음'}`);}r.amounts.forEach((a,i)=>{const x=record.products[i];lines.push('',`${brand(x.brand)} · ${x.name}`,`하루 ${fmt(a.grams,1)} g / 한 끼 ${fmt(a.perMeal,1)} g / 하루 ${p.meals}회`,a.packs!==null?`하루 ${fmt(a.packs,2)} 캔·파우치 (${x.packGrams} g 포장)`:'',`적용 열량: ${energyLabel(x)} · ${x.energySource}`);});lines.push('',`재평가 예정일: ${p.recheck||'담당 수의사와 일정 확인'}`,`급여 안내: ${p.instructions||'계량 저울로 급여량을 확인하고 실제 섭취량과 체중 변화를 기록하세요.'}`);if(!owner)lines.push(...r.warnings.map(x=>'검토 사항: '+x),'수의사 검토 완료 · 제품 포장 열량 확인 완료',...record.products.map(x=>`제품 자료: ${x.url||'사용자 등록'} / 확인일 ${x.checkedAt}`));return lines.join('\n');}
  $('save').addEventListener('click',()=>{try{const r=makeRecord();if(!r.patient.name)return toast('환자명 또는 차트 번호를 입력하세요.');if(persist(custom,[r,...records]))toast('급여 계획을 환자 기록에 저장했습니다.');}catch(e){toast(e.message);}});
  function showText(text){const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-label','복사할 진료 요약');area.style.width='100%';area.rows=20;const dialog=document.createElement('dialog');dialog.append(area);const b=document.createElement('button');b.textContent='닫기';b.onclick=()=>{dialog.close();dialog.remove();};dialog.append(b);document.body.append(dialog);dialog.showModal();area.select();}
  $('copy').addEventListener('click',async()=>{let t;try{t=report(makeRecord());await navigator.clipboard.writeText(t);toast('진료 요약을 복사했습니다.');}catch(e){if(t)showText(t);else toast(e.message);}});
  function printRecord(r){$('print-area').innerHTML=`<h1>환자 식이 급여 안내</h1><p>${esc(report(r,true).split('\n').slice(1).join('\n'))}</p><hr><p>담당 수의사가 검토한 초기 급여 계획입니다. 실제 섭취량과 체중·신체 상태를 확인하여 재평가 시 조정합니다.</p>`;window.print();}
  $('print').addEventListener('click',()=>{try{printRecord(makeRecord());}catch(e){toast(e.message);}});
  function renderLibrary(){const query=$('library-search').value.toLowerCase();const list=catalog().filter(x=>x.name.toLowerCase().includes(query)&&($('library-species').value==='all'||x.species===$('library-species').value));$('library-body').innerHTML=list.map(x=>`<tr><td><b>${brand(x.brand)}</b><br>${esc(x.name)}<small>${esc(x.notes)}</small></td><td>${species(x.species)}<br>${x.type==='dry'?'건식':'습식'}${x.packGrams?'<small>'+x.packGrams+' g 포장</small>':''}</td><td>${esc(x.purposes.map(k=>E.labels[k]).join(' · '))}</td><td>${esc(energyLabel(x))}<small>${x.labelConfirmed?'포장 확인 완료':'포장 대조 필요'}</small></td><td>${safeURL(x.url)?`<a href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">공식 자료</a>`:'사용자 등록'}<small>${esc(x.checkedAt)}</small></td><td><button data-edit="${esc(x.id)}">수정</button><button data-use="${esc(x.id)}" style="margin-top:8px">직접 선택</button></td></tr>`).join('')||'<tr><td colspan="6">검색 결과가 없습니다.</td></tr>';}
  for(const id of ['library-search','library-species'])$(id).addEventListener('input',renderLibrary);
  $('library-body').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)openEditor(product(b.dataset.edit));if(b.dataset.use){const x=product(b.dataset.use);if(x.species!==patient().species)return toast('환자의 동물 종류와 제품 대상이 다릅니다.');selected=x.id;secondary=null;manualChoice=true;invalidate();switchTab('plan');}});
  function openEditor(x){$('product-form').reset();$('edit-id').value=x?.id||'';if(x){for(const [id,value]of Object.entries({'edit-brand':x.brand,'edit-name':x.name,'edit-species':x.species,'edit-type':x.type,'edit-purpose':x.purposes[0],'edit-energy':x.energy??'','edit-unit':x.energyUnit,'edit-pack':x.packGrams??'','edit-energy-source':x.energySource,'edit-url':x.url,'edit-notes':x.notes}))$(id).value=value;$('edit-confirmed').checked=x.labelConfirmed;}$('product-dialog').showModal();}
  $('add-product').addEventListener('click',()=>openEditor(null));$('close-dialog').addEventListener('click',()=>$('product-dialog').close());
  $('product-form').addEventListener('submit',event=>{event.preventDefault();try{const old=product($('edit-id').value),purpose=$('edit-purpose').value;const x={...(old||{}),id:old?.id||'user-'+crypto.randomUUID(),name:$('edit-name').value.trim(),brand:$('edit-brand').value,species:$('edit-species').value,type:$('edit-type').value,purposes:old?.purposes[0]===purpose?old.purposes:[purpose],energy:$('edit-energy').value.trim()?Number($('edit-energy').value):null,energyUnit:$('edit-unit').value,packGrams:$('edit-pack').value.trim()?Number($('edit-pack').value):null,energySource:$('edit-energy-source').value.trim(),labelConfirmed:$('edit-confirmed').checked,url:$('edit-url').value.trim(),notes:$('edit-notes').value,minAge:old?.minAge||12,maxAge:old?.maxAge||361,maxWeight:old?.maxWeight||null,contra:old?.contra||[],checkedAt:date()};E.validateProduct(x);if(persist([...custom.filter(p=>p.id!==x.id),x])){$('product-dialog').close();invalidate();renderLibrary();toast('제품 정보를 저장했습니다.');}}catch(e){toast(e.message);}});
  function renderRecords(){const q=$('record-search').value.trim().toLowerCase();const list=records.filter(r=>r.patient.name.toLowerCase().includes(q));$('records-list').innerHTML=list.length?list.map(r=>{const prev=records.filter(x=>x.patient.name===r.patient.name&&x.patient.species===r.patient.species&&x.savedAt<r.savedAt).sort((a,b)=>b.savedAt.localeCompare(a.savedAt))[0];const change=prev?Number(r.patient.weight)-Number(prev.patient.weight):null;return`<article class="record"><div><h3>${esc(r.patient.name)} <span class="pill">${species(r.patient.species)}</span></h3><p>${esc(r.date)} · ${fmt(Number(r.patient.weight),1)} kg · BCS ${esc(r.patient.bcs)}/9 · ${fmt(r.result.total)} kcal/일</p><p>${r.products.map(x=>`${brand(x.brand)} ${esc(x.name)}`).join(' + ')}</p>${prev?`<p class="trend">이전 기록(${esc(prev.date)}) 대비 ${change>0?'+':''}${fmt(change,1)} kg</p>`:''}<p>재평가: ${esc(r.patient.recheck||'미지정')}</p></div><div class="actions"><button data-load="${esc(r.id)}">재진 계획 작성</button><button data-print-record="${esc(r.id)}">안내문</button><button data-summary="${esc(r.id)}">진료 요약</button></div></article>`;}).join(''):'<div class="empty">저장된 급여 계획이 없습니다.</div>';}
  $('record-search').addEventListener('input',renderRecords);
  $('records-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.load||b.dataset.printRecord||b.dataset.summary,r=records.find(x=>x.id===id);if(!r)return;if(b.dataset.printRecord)return printRecord(r);if(b.dataset.summary)return showText(report(r));if($('weight').value&&!confirm('현재 입력을 저장된 환자 정보로 바꿀까요?'))return;setPatient(r.patient);selected=r.products[0]?.id||null;secondary=r.products[1]?.id||null;invalidate();switchTab('plan');toast('현재 제품 자료로 다시 계산했습니다. 변경된 조건을 검토하세요.');});
  $('backup').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),custom,records},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`VetDiet-backup-${date()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('제품 정보와 환자 기록을 백업했습니다.');});
  function validatePatient(p){const choices={species:['dog','cat'],life:['adult','senior','growth','reproduction','hospital'],neuter:['yes','no'],activity:['normal','low','high'],mcs:['normal','mild','moderate','severe'],goal:['maintain','loss','gain'],energyMode:['auto','factor','manual']};if(!p||typeof p!=='object')throw Error('환자 자료 오류');for(const [k,v]of Object.entries(choices))if(!v.includes(p[k]))throw Error('환자 상태 형식 오류');if(!Array.isArray(p.conditions)||p.conditions.some(k=>!['renal','urinary','gi','lowfat','allergy','other'].includes(k)))throw Error('질환 항목 오류');for(const k of ['name','clinical','instructions','recheck'])if(typeof p[k]!=='string'||p[k].length>3000)throw Error('환자 메모 형식 오류');for(const k of ['weight','age','bcs','target','factor','manual','treats','meals','ratio'])if(!['string','number'].includes(typeof p[k]))throw Error('수치 형식 오류');if(typeof p.mixed!=='boolean')throw Error('급여 방식 오류');}
  function validateBackup(d){if(!d||d.version!==1||!Array.isArray(d.custom)||!Array.isArray(d.records)||d.custom.length>2000||d.records.length>10000)throw Error('지원하지 않는 백업 형식입니다.');const c=d.custom.map(p=>{E.validateProduct(p);if(!Array.isArray(p.contra)||p.contra.some(x=>typeof x.code!=='string'||typeof x.label!=='string'))throw Error('제품 제한사항 오류');if(typeof p.checkedAt!=='string')throw Error('제품 확인일 오류');return p;});const rows=d.records.map(r=>{if(!r||typeof r.id!=='string'||r.id.length>100||typeof r.savedAt!=='string'||!Number.isFinite(Date.parse(r.savedAt))||typeof r.date!=='string'||!Array.isArray(r.products)||r.products.length<1||r.products.length>2)throw Error('환자 기록 형식 오류');validatePatient(r.patient);r.products.forEach(E.validateProduct);const result=E.calculate(r.patient,r.products[0],r.products[1]);if(!result.ok)throw Error('저장 계획의 계산 조건이 올바르지 않습니다.');return{...r,result};});return{custom:c,records:rows};}
  $('restore').addEventListener('click',()=>$('restore-file').click());$('restore-file').addEventListener('change',async()=>{const file=$('restore-file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('백업 파일은 5 MB 이하로 선택하세요.');const d=validateBackup(JSON.parse(await file.text())),cc=new Map(custom.map(p=>[p.id,p]));d.custom.forEach(p=>{if(!cc.has(p.id))cc.set(p.id,p);});const rr=new Map(records.map(r=>[r.id,r]));d.records.forEach(r=>{if(!rr.has(r.id))rr.set(r.id,r);});if(persist([...cc.values()],[...rr.values()].sort((a,b)=>b.savedAt.localeCompare(a.savedAt)))){invalidate();renderRecords();toast('백업을 합쳤습니다. 같은 ID의 기존 자료는 유지했습니다.');}}catch(e){toast('백업을 불러오지 못했습니다: '+e.message);}finally{$('restore-file').value='';}});
  $('guide-content').innerHTML=`<h2>계산의 시작점</h2><div class="formula">RER = 70 × 체중(kg)<sup>0.75</sup></div><p>하루 목표 열량은 RER에 상태별 계수를 적용한 초기 추정값입니다. 유지 계획은 현재 체중, 감량 계획은 수의사가 정한 목표 체중을 기준으로 계산합니다. BCS로 목표 체중을 자동 추정하지 않습니다.</p><table><thead><tr><th>상태</th><th>강아지 · 기본 계수</th><th>고양이 · 기본 계수</th></tr></thead><tbody><tr><td>중성화 성체</td><td>1.6</td><td>1.2</td></tr><tr><td>비중성화 성체</td><td>1.8</td><td>1.4</td></tr><tr><td>낮은 활동량 / 비만 경향</td><td>1.2</td><td>1.0</td></tr><tr><td>감량 · 목표 체중 기준</td><td>1.0</td><td>0.8</td></tr></tbody></table><p>AAHA 범위 내에서 선택한 기본값입니다. 실제 섭취량과 체중·BCS·MCS 변화를 확인해 조정하세요. 질병, 근육 감소, BCS 3 이하, 증량 및 높은 활동량 환자는 계수 또는 열량을 직접 지정합니다. 노령이라는 이유만으로 일괄 감량하지 않습니다.</p><h2>사료량과 혼합 급여</h2><p>사료 공급 열량 = 하루 목표 열량 − 기타 음식 열량<br>하루 급여량(g) = 제품에 배분한 열량 ÷ kcal/g<br>kcal/kg ÷ 1,000 = kcal/g · kcal/100g ÷ 100 = kcal/g<br>캔 열량 ÷ 캔 중량(g) = kcal/g</p><p>혼합 비율은 열량 비율입니다. 중간값은 반올림하지 않으며, 급여 g은 소수점 한 자리로 표시합니다. 캔·파우치 수는 등록된 해당 포장 중량을 기준으로 계산합니다.</p><h2>사료 후보의 의미</h2><p>종·등록 연령·제품 용도·체중 범위와 기록된 제한사항으로 후보를 좁힙니다. 질병 단계와 검사값을 해석하는 임상 추천 엔진은 아직 포함되지 않았습니다. 복합 질환은 등록 용도가 모든 조건을 충족하는 제품만 후보에 표시하며, 후보가 없으면 자동 대체하지 않습니다. 원료 알레르기 적합성과 미등록 금기는 자동 판정하지 않습니다.</p><p>영양성분은 출처의 기준(DM/급여 상태/열량 기준, 평균값/보증값)을 함께 기록합니다. 서로 다른 기준의 성분 자동 환산이나 영양소 충족 판정은 지원하지 않습니다. 제한사항이 없다는 표시는 무제한 사용 가능을 의미하지 않습니다.</p><h2>제품 자료</h2><p>한국 공식 페이지 확인일: 2026-10-07. 로얄캐닌 열량에는 공식 제품 데이터의 글로벌 기본값이 포함되므로 실제 국내 포장과 대조하세요. 본문과 제품 데이터가 충돌한 값은 비워 두었습니다. 열량 미확인 제품은 포장값을 입력해야 합니다. 포장 용량·배합이 바뀌면 제품 정보를 갱신하세요.</p><h2>지원 범위와 기록</h2><p>성체 외래 환자의 급여 계획 작성용입니다. 성장기·임신·수유·입원 영양, 재급식 및 경관 급여 프로토콜은 별도 개발 범위입니다. 기록과 사용자 제품 자료는 이 브라우저에 저장되며 외부로 전송되지 않습니다. 제품 출처 링크는 제조사 사이트로 이동합니다. 브라우저 데이터 삭제 전에 백업하세요.</p><h2>근거 자료</h2><ul><li><a href="https://www.aaha.org/resources/2021-aaha-nutrition-and-weight-management-guidelines/weight-reduction-in-the-obese-pet/" target="_blank" rel="noopener noreferrer">AAHA 2021 · RER, 상태별 계수와 체중 관리</a></li><li><a href="https://www.aaha.org/resources/2021-aaha-nutrition-and-weight-management-guidelines/feeding-plans-for-healthy-appropriate-weight-cats-and-dogs/" target="_blank" rel="noopener noreferrer">AAHA · 섭취 열량 평가와 급여 계획</a></li><li><a href="https://wsava.org/global-guidelines/global-nutrition-guidelines/" target="_blank" rel="noopener noreferrer">WSAVA · 영양 평가, BCS와 MCS</a></li></ul>`;
  if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_current_feeding_plan',title:'현재 급여 계획 확인',description:'현재 화면의 환자 정보와 검토 중인 급여량 계산을 읽습니다. 저장하거나 처방을 확정하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('인수가 필요하지 않습니다.');return{patient:patient(),result:lastResult,reviewed:$('reviewed').checked};}})).catch(()=>{});}catch{}}
  render();
})();
